 private static final boolean ROTATE=Boolean.getBoolean("vandorlabs.applianceArmRotate");private static final BlockPos ROOT=new BlockPos(31,100,31),SOURCE=ROTATE?ROOT.east(2):ROOT.above(2);private static ServerLevel world;private static Actor actor;private static int stage,ticks,checks,fractional,endpointWait;private static boolean running,leaseChecked;private static ItemStack printerChip,scannerChip,original;private static BlockPos partner(BlockPos source){return ROTATE?source.above():source.east();}
