 private static String phase(){return System.getProperty("vandorlabs.applianceArmPhase","");}private static boolean enabled(){return Boolean.getBoolean("vandorlabs.applianceArmChecks");}private static void need(boolean valid,String why){checks++;if(!valid)throw new AssertionError("Appliance arm stage="+stage+" tick="+ticks+": "+why);}private static NativeGearEntity root(){return NativeGearFormation.at(world,ROOT);}
