 public static void staged(ServerLevel level,com.vandorlabs.neoforge.appliances.NativeApplianceEntity owner){var cell=NativeGearSnapshot.capture(level,owner.getBlockPos(),false);var tile=NativeGearSnapshot.stage(level,cell,false);if(!(tile instanceof com.vandorlabs.neoforge.appliances.NativeApplianceEntity t)||t.inert()||!ItemStack.matches(owner.chipStack(),t.chipStack())||!ItemStack.matches(owner.frameStack(),t.frameStack())||!ItemStack.matches(owner.inkStack(),t.inkStack())||!ItemStack.matches(owner.paperStack(),t.paperStack()))throw new AssertionError("Detached appliance strict ownership staging");}
 public static void rotations(ServerLevel level,com.vandorlabs.neoforge.appliances.NativeApplianceEntity owner){try{var method=NativeGearPayload.class.getDeclaredMethod("rotate",net.minecraft.world.level.block.state.BlockState.class,NativeGearPayload.Transform.class,boolean.class);method.setAccessible(true);var cell=NativeGearSnapshot.capture(level,owner.getBlockPos(),false);for(var face:Direction.Plane.HORIZONTAL)for(int quarter=0;quarter<4;quarter++){double theta=quarter*Math.PI/2,cos=Math.rint(Math.cos(theta)),sin=Math.rint(Math.sin(theta));var transform=new NativeGearPayload.Transform(cos,0,sin,0,1,0,-sin,0,cos,0,0,0);var state=cell.state.setValue(com.vandorlabs.neoforge.appliances.NativeApplianceBlock.FACING,face);var rotated=(net.minecraft.world.level.block.state.BlockState)method.invoke(null,state,transform,true);var v=transform.vector(face.getStepX(),0,face.getStepZ());if(rotated.getValue(com.vandorlabs.neoforge.appliances.NativeApplianceBlock.FACING)!=Direction.getNearest(v.x,v.y,v.z))throw new AssertionError("Appliance yaw facing");var staged=(com.vandorlabs.neoforge.appliances.NativeApplianceEntity)NativeGearSnapshot.stage(level,new NativeGearSnapshot.Cell(cell.pos,rotated,cell.tile()),false);if(!ItemStack.matches(staged.chipStack(),owner.chipStack())||!ItemStack.matches(staged.inkStack(),owner.inkStack())||!ItemStack.matches(staged.paperStack(),owner.paperStack())||!ItemStack.matches(staged.frameStack(),owner.frameStack()))throw new AssertionError("Yaw transforms physical inventory");}System.out.println("[vandorlabs][appliances] rotation PASS 16yawStates/exactPrivateStaging");}catch(ReflectiveOperationException error){throw new AssertionError("Appliance yaw adapter",error);}}
 private static void exact(com.vandorlabs.neoforge.appliances.NativeApplianceEntity t){need(!t.inert(),"healthy appliance");if(t.scanner()){need(ItemStack.matches(t.chipStack(),scannerChip)&&ItemStack.matches(t.frameStack(),original),"exact scanner chip and retained original map");}else need(ItemStack.matches(t.chipStack(),printerChip)&&t.inkStack().is(Items.INK_SAC)&&t.inkStack().getCount()==2&&t.paperStack().is(Items.PAPER)&&t.paperStack().getCount()==3,"exact printer chip and consumables");}
