 private static void nativeEndpoint(NativeGearEntity arm){int count=0;for(var cell:arm.payload().cells())if(cell.state.getBlock() instanceof com.vandorlabs.neoforge.appliances.NativeApplianceBlock){need(world.getBlockEntity(cell.pos) instanceof com.vandorlabs.neoforge.appliances.NativeApplianceEntity,"native journal endpoint appliance");var appliance=(com.vandorlabs.neoforge.appliances.NativeApplianceEntity)world.getBlockEntity(cell.pos);exact(appliance);if(ROTATE)need((appliance.getBlockState().getValue(com.vandorlabs.neoforge.appliances.NativeApplianceBlock.FACING)==Direction.NORTH)==(stage==5),"yaw changes facing and cold reversal restores original facing");count++;}need(count==2&&drops().isEmpty(),"native journal exact two appliances");}
 @SubscribeEvent public static void started(ServerStartedEvent e){if(!enabled())return;try{world=e.getServer().overworld();for(int x=1;x<=2;x++)for(int z=1;z<=2;z++){world.setChunkForced(x,z,true);world.getChunk(x,z);}actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);actor.setPos(ROTATE?34.5:27.5,100,ROTATE?34.5:31.5);printerChip=com.vandorlabs.neoforge.credentials.NativeChipTypes.variant("journal");com.vandorlabs.neoforge.screen.NativeChipJournal.write(printerChip,true,"Arm inventory",new String[]{"Retain private document"});scannerChip=printerChip.copy();if(phase().equals("read")){original=new ItemStack(Items.FILLED_MAP);original.set(DataComponents.MAP_ID,new net.minecraft.world.level.saveddata.maps.MapId(0));}else{original=MapItem.create(world,2100000,-1900000,(byte)4,true,false);need(original.get(DataComponents.MAP_ID).id()==0,"isolated fixture first vanilla map id");java.util.Arrays.fill(MapItem.getSavedData(original,world).colors,(byte)50);MapItem.getSavedData(original,world).setDirty();}if(phase().equals("read")){stage=4;running=true;return;}for(var p:BlockPos.betweenClosed(ROOT.offset(-5,-2,-5),ROOT.offset(5,9,5)))world.setBlock(p,p.getY()==99?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),3);var settings=NativeGearSettings.defaults().choices();settings.putBoolean("CarryLoad",!ROTATE);settings.putBoolean("RotatePayload",ROTATE);settings.putBoolean("JoinArms",true);settings.putInt("LoadHeight",3);settings.putDouble("ActiveExtension",2);var tag=new CompoundTag();tag.put(NativeGearItem.SETTINGS,settings);var stack=new ItemStack(NativeGearBindings.ITEMS.get((ROTATE?NativeGearDefinition.ROTATING:NativeGearDefinition.EXTENDER).id),4);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));actor.setItemInHand(InteractionHand.MAIN_HAND,stack);if(ROTATE)for(int y=0;y<2;y++)world.setBlock(ROOT.west().above(y),Blocks.STONE.defaultBlockState(),3);for(int x=0;x<2;x++)for(int y=0;y<2;y++){var support=ROTATE?ROOT.west().above(x).east(y):ROOT.east(x).above(y-1);var face=ROTATE?Direction.EAST:Direction.UP;need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(face.getStepX()*.5,face.getStepY()*.5,face.getStepZ()*.5),face,support,false)).consumesAction(),"ordinary Survival joined Extender placement "+x+","+y);}need(stack.isEmpty(),"four arm items consumed once");actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);running=true;}catch(Throwable error){fail(error);}}
 @SubscribeEvent public static void tick(ServerTickEvent.Post e){if(!running)return;try{need(++ticks<1600,"bounded async arm ownership root="+root()+" columns="+(root()==null?-1:root().columns().size())+" error="+(root()==null?"missing":root().error()));var arm=root();if(arm==null||arm.inert()||!arm.controller()||!arm.completeMembers())return;need(!arm.blocked(),"arm remains unobstructed "+arm.error());if(stage==0){if(arm.assembly().columnHeight()!=2||arm.columns().size()!=2)return;world.setBlock(SOURCE,com.vandorlabs.neoforge.appliances.NativeApplianceBindings.BLOCKS.get("printer").defaultBlockState(),3);world.setBlock(partner(SOURCE),com.vandorlabs.neoforge.appliances.NativeApplianceBindings.BLOCKS.get("scanner").defaultBlockState(),3);stage=1;return;}if(stage==1){var printer=(com.vandorlabs.neoforge.appliances.NativeApplianceEntity)world.getBlockEntity(SOURCE);var scanner=(com.vandorlabs.neoforge.appliances.NativeApplianceEntity)world.getBlockEntity(partner(SOURCE));need(printer.replaceChip(ItemStack.EMPTY,printerChip)&&scanner.replaceChip(ItemStack.EMPTY,scannerChip),"install physical appliance chips");printer.setItem(1,new ItemStack(Items.INK_SAC,2));printer.setItem(2,new ItemStack(Items.PAPER,3));scanner.setItem(1,original);nativeInventory(SOURCE);staged(world,printer);staged(world,scanner);arm.authorize(actor);need(arm.command(false),"activate ordinary appliance payload");stage=2;return;}if(stage==2||stage==5){if(!leaseChecked&&NativeGearHolds.reserved(world,SOURCE)&&world.getBlockEntity(SOURCE) instanceof com.vandorlabs.neoforge.appliances.NativeApplianceEntity target){var before=target.saveWithFullMetadata(world.registryAccess());need(!target.replaceChip(target.chipStack(),ItemStack.EMPTY)&&target.removeItem(1,1).isEmpty(),"pending journal refuses chip and consumable extraction");target.setItem(1,ItemStack.EMPTY);need(before.equals(target.saveWithFullMetadata(world.registryAccess())),"pending journal inventory setters leave snapshot exact");leaseChecked=true;}if(arm.payload()!=null&&!arm.payload().materialized()){inventory(arm.payload().cells());var ids=new java.util.ArrayList<net.minecraft.world.level.saveddata.maps.MapId>();NativeAppliancePayloadMaps.visit(arm,ids::add);need(ids.size()==1&&ids.getFirst().equals(original.get(DataComponents.MAP_ID)),"carried hydration bridge returns sole map identity without private chip data");if(fractional==0){int chips=0,books=0,ink=0,paper=0;for(int index=0;index<arm.payload().size();index++)for(var drop:NativeGearHarvestReceipt.prepare(arm,actor,index).drops()){var stack=drop.stack();if(com.vandorlabs.neoforge.credentials.NativeCredentialItems.accepts(stack,true)){chips+=stack.getCount();need(ItemStack.matches(stack,printerChip),"captured mining exact private chip");}if(stack.is(Items.FILLED_MAP)){books+=stack.getCount();need(ItemStack.matches(stack,original),"captured mining retained original");}if(stack.is(Items.INK_SAC))ink+=stack.getCount();if(stack.is(Items.PAPER))paper+=stack.getCount();}need(chips==2&&books==1&&ink==2&&paper==3,"captured mining inventory exactly once");}fractional++;}double target=stage==2?0:1;if(arm.progress()!=target||NativeGearJournal.busy(arm))return;if(arm.payload()==null||!arm.payload().materialized()){need(++endpointWait<120,"bounded native endpoint publication progress="+arm.progress()+" endpoint="+(arm.payload()==null?-1:arm.payload().endpoint(arm,arm.progress()).size())+" cached="+(arm.payload()==null?"none":arm.cachedEndpointFailure(arm.payload()))+" error="+arm.error());return;}endpointWait=0;nativeEndpoint(arm);if(stage==5)nativeInventory(SOURCE);if(stage==2){need(fractional>0,"real fractional captured ownership exercised");need(leaseChecked,"actual reserved asynchronous prepare mutation check executed");world.getServer().saveEverything(false,true,true);finish("save");}else finish("read");return;}if(stage==4){need(arm.progress()==0&&arm.payload()!=null&&arm.payload().materialized(),"cold active endpoint retained");nativeEndpoint(arm);arm.authorize(actor);need(arm.command(true),"cold occupied appliances reverse to original native endpoint");stage=5;}}catch(Throwable error){fail(error);}}
